const provider = $('Webhook — Receive Transcript').item.json.body.provider || 'gemini';

let rawText = '';
try {
  if (provider === 'mistral') {
    rawText = $('AI Agent — Mistral').item.json.output;
  } else {
    rawText = $('AI Agent — Gemini').item.json.output;
  }
} catch(e) {
  return { json: { success: false, error: 'Could not read agent output: ' + e.message } };
}

if (!rawText || !rawText.trim()) {
  return { json: { success: false, error: 'AI agent returned empty output' } };
}

const clean = rawText.replace(/```json\n?|```\n?/g, '').trim();
const jsonMatch = clean.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  return { json: { success: false, error: 'No JSON found in response', raw: rawText.substring(0, 300) } };
}

// Fix common AI JSON mistakes: trailing commas, comments
const fixedJson = jsonMatch[0]
  .replace(/,\s*([}\]])/g, '$1')
  .replace(/\/\/[^\n]*/g, '')
  .replace(/\/\*[\s\S]*?\*\//g, '');

let result;
try {
  result = JSON.parse(fixedJson);
} catch(e) {
  return { json: { success: false, error: 'JSON parse failed: ' + e.message, raw: rawText.substring(0, 300) } };
}

if (!Array.isArray(result.action_items)) result.action_items = [];
if (!Array.isArray(result.decisions)) result.decisions = [];
if (!result.summary) result.summary = 'Meeting summary not available.';
if (!result.email_subject) result.email_subject = 'Meeting Follow-up';
if (!result.email_body) result.email_body = '';

result.action_items = result.action_items.map((item, i) => ({
  ...item,
  id: item.id ?? i + 1,
  priority: ['HIGH', 'MEDIUM', 'LOW'].includes(item.priority) ? item.priority : 'MEDIUM',
  due: item.due || 'Not specified',
  owner: item.owner || 'Team',
}));

result.meeting_id = 'mtg_' + Date.now();
result.provider = provider;
result.analyzed_at = new Date().toISOString();

return { json: { success: true, data: result } };

const input = $input.item.json;
if (!input.success || !input.data) {
  return { json: input };
}

const result = input.data;
const items = result.action_items || [];
const decisions = result.decisions || [];

const ownedItems = items.filter(i => i.owner && i.owner !== 'Team').length;
const datedItems = items.filter(i => i.due && i.due !== 'Not specified').length;
const highItems = items.filter(i => i.priority === 'HIGH').length;

let score = 0;
score += Math.min(items.length * 8, 30);
score += Math.min(decisions.length * 10, 20);
score += Math.min(ownedItems * 6, 30);
score += Math.min(datedItems * 5, 20);
score = Math.min(score, 100);

const grade = score >= 80 ? 'A' : score >= 60 ? 'B' : score >= 40 ? 'C' : 'D';
const score_label = score >= 80 ? 'Excellent' : score >= 60 ? 'Good' : score >= 40 ? 'Fair' : 'Needs Improvement';

return {
  json: {
    success: true,
    data: {
      ...result,
      score,
      grade,
      score_label,
      high_priority_count: highItems
    }
  }
};

const d = $json.data;
return {
  json: {
    meeting_id: d.meeting_id,
    date: new Date(d.analyzed_at).toLocaleString('en-GB'),
    provider: d.provider,
    summary: d.summary,
    decisions: (d.decisions || []).join(' | '),
    items_count: d.action_items.length,
    high_priority: d.action_items.filter(i => i.priority === 'HIGH').length,
    owners: [...new Set(d.action_items.map(i => i.owner))].join(', '),
    score: d.score,
    grade: d.grade,
    items_json: JSON.stringify(d.action_items)
  }
};

const body = $json.body;
const items = body.approved_items || [];

let emailBody;
if (body.body && body.body.trim()) {
  // Use the HTML body built by the frontend
  emailBody = body.body.trim();
} else {
  // Fallback: generate HTML when frontend body is missing
  const priorityStyle = (p) =>
    p === 'HIGH'   ? 'background:#fee2e2;color:#dc2626;' :
    p === 'MEDIUM' ? 'background:#fef3c7;color:#d97706;' :
                     'background:#d1fae5;color:#059669;';
  const itemsHtml = items.map((item, i) => `
    <div style="border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin:10px 0;">
      <p style="font-weight:700;font-size:14px;margin:0 0 8px;color:#111827;">${i+1}. ${item.task}</p>
      <span style="display:inline-block;padding:3px 10px;border-radius:9999px;font-size:11px;font-weight:700;${priorityStyle(item.priority)}">${item.priority}</span>
      &nbsp;<span style="font-size:12px;color:#6b7280;">Owner: <strong>${item.owner}</strong> &nbsp;·&nbsp; Due: ${item.due}</span>
    </div>`).join('');
  emailBody = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:24px;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;">
<div style="max-width:620px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);">
  <div style="background:linear-gradient(135deg,#4f46e5,#0ea5e9);padding:28px 32px;">
    <h1 style="margin:0;font-size:22px;font-weight:800;color:#fff;">Meeting Follow-up</h1>
    <p style="margin:6px 0 0;font-size:13px;color:rgba(255,255,255,0.8);">Action Items &amp; MOM</p>
  </div>
  <div style="padding:28px 32px;">
    <p style="font-size:11px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:#9ca3af;margin:0 0 14px;">Action Items</p>
    ${itemsHtml}
  </div>
  <div style="padding:16px 32px;background:#f9fafb;border-top:1px solid #f3f4f6;text-align:center;">
    <p style="font-size:12px;color:#6b7280;margin:0;">Please update your progress before the next check-in.</p>
    <p style="font-size:11px;color:#9ca3af;margin:4px 0 0;">Sent via MeetingMind</p>
  </div>
</div></body></html>`;
}

return {
  json: {
    to: body.to || 'team@company.com',
    cc: body.cc || '',
    subject: body.subject || 'Meeting Follow-up — Action Items',
    message: emailBody,
    item_count: items.length
  }
};

const body = $('Webhook — Send Email').item.json.body;
const items = body.approved_items || [];
const today = new Date();
today.setHours(0, 0, 0, 0);

const events = items
  .filter(item => item.due && item.due !== 'Not specified')
  .map(item => {
    let eventDate = new Date(today);
    const due = item.due.toLowerCase();

    if (due.includes('today') || due.includes('eod')) {
      // keep today
    } else if (due.includes('tomorrow')) {
      eventDate.setDate(today.getDate() + 1);
    } else if (due.includes('monday')) {
      const d = today.getDay(), diff = (1 + 7 - d) % 7 || 7;
      eventDate.setDate(today.getDate() + diff);
    } else if (due.includes('tuesday')) {
      const d = today.getDay(), diff = (2 + 7 - d) % 7 || 7;
      eventDate.setDate(today.getDate() + diff);
    } else if (due.includes('wednesday')) {
      const d = today.getDay(), diff = (3 + 7 - d) % 7 || 7;
      eventDate.setDate(today.getDate() + diff);
    } else if (due.includes('thursday')) {
      const d = today.getDay(), diff = (4 + 7 - d) % 7 || 7;
      eventDate.setDate(today.getDate() + diff);
    } else if (due.includes('friday')) {
      const d = today.getDay(), diff = (5 + 7 - d) % 7 || 7;
      eventDate.setDate(today.getDate() + diff);
    } else {
      eventDate.setDate(today.getDate() + 3);
    }

    eventDate.setHours(9, 0, 0, 0);
    const endDate = new Date(eventDate);
    endDate.setHours(9, 30, 0, 0);

    return {
      json: {
        title: `[${item.priority}] ${item.task}`,
        description: `Owner: ${item.owner}\nDue: ${item.due}\nPriority: ${item.priority}\n\nCreated by MeetingMind`,
        start: eventDate.toISOString(),
        end: endDate.toISOString()
      }
    };
  });

return events;

const rows = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);

const dueToday = [];
const dueTomorrow = [];

for (const row of rows) {
  const itemsJson = row.json['items_json'];
  if (!itemsJson) continue;
  try {
    const items = JSON.parse(itemsJson);
    for (const item of items) {
      if (!item.due || item.due === 'Not specified') continue;
      const due = item.due.toLowerCase();
      const entry = { task: item.task, owner: item.owner, priority: item.priority, due: item.due };
      if (due.includes('today') || due.includes('eod')) {
        dueToday.push(entry);
      } else if (due.includes('tomorrow')) {
        dueTomorrow.push(entry);
      }
    }
  } catch(e) { /* skip malformed rows */ }
}

const allDue = [...dueToday, ...dueTomorrow];
return [{ json: { has_due: allDue.length > 0, due_today: dueToday, due_tomorrow: dueTomorrow, count: allDue.length } }];

const { due_today, due_tomorrow } = $json;

const priorityStyle = (p) =>
  p === 'HIGH'   ? 'background:#fee2e2;color:#dc2626;' :
  p === 'MEDIUM' ? 'background:#fef3c7;color:#d97706;' :
                   'background:#d1fae5;color:#059669;';

const buildSection = (items, heading, borderColor) => {
  if (!items.length) return '';
  const rows = items.map(item =>
    `<tr>
      <td style="padding:10px 12px;border-bottom:1px solid #f3f4f6;font-size:14px;color:#111827;font-weight:500;">${item.task}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #f3f4f6;font-size:13px;color:#6b7280;white-space:nowrap;">${item.owner}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #f3f4f6;"><span style="padding:2px 8px;border-radius:9999px;font-size:11px;font-weight:700;${priorityStyle(item.priority)}">${item.priority}</span></td>
    </tr>`
  ).join('');
  return `
    <div style="margin-bottom:24px;">
      <div style="border-left:3px solid ${borderColor};padding-left:12px;margin-bottom:12px;">
        <p style="font-size:11px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:#9ca3af;margin:0;">${heading}</p>
      </div>
      <table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">
        <thead><tr style="background:#f9fafb;">
          <th style="text-align:left;padding:8px 12px;font-size:11px;color:#6b7280;font-weight:600;">Task</th>
          <th style="text-align:left;padding:8px 12px;font-size:11px;color:#6b7280;font-weight:600;">Owner</th>
          <th style="text-align:left;padding:8px 12px;font-size:11px;color:#6b7280;font-weight:600;">Priority</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
};

const todaySection    = buildSection(due_today,    'Due Today',    '#ef4444');
const tomorrowSection = buildSection(due_tomorrow, 'Due Tomorrow', '#f59e0b');
const todayStr = new Date().toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long' });

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:24px;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;">
<div style="max-width:600px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);">
  <div style="background:linear-gradient(135deg,#f59e0b,#ef4444);padding:28px 32px;">
    <h1 style="margin:0;font-size:20px;font-weight:800;color:#fff;">&#9200; Action Items Due Soon</h1>
    <p style="margin:6px 0 0;font-size:13px;color:rgba(255,255,255,0.85);">${todayStr}</p>
  </div>
  <div style="padding:28px 32px;">
    <p style="font-size:14px;color:#374151;margin:0 0 20px;">Hi team, this is your daily MeetingMind reminder. The following action items need attention:</p>
    ${todaySection}${tomorrowSection}
  </div>
  <div style="padding:16px 32px;background:#f9fafb;border-top:1px solid #f3f4f6;text-align:center;">
    <p style="font-size:12px;color:#6b7280;margin:0;">Please ensure these are completed on time.</p>
    <p style="font-size:11px;color:#9ca3af;margin:4px 0 0;">Sent automatically by MeetingMind</p>
  </div>
</div></body></html>`;

const subject = `&#9200; MeetingMind Reminder \u2014 ${$json.count} item(s) due soon (${todayStr})`;
return [{ json: { subject, html } }];
